母函数
hdu1028
ymc 2008/09/25
题目大意：
N=a[1]+a[2]+...+a[m],a[i]>0,1<=m<=N。
总共有多少种不同的方程？
4=1+3=3+1是同一种。
解题思路：
f(x)=(1+x+x^2+...)(1+x^2+x^4+...)(1+x^3+x^6+...)..(1+x^N+...)
其中x^n次方的系数就是构成总值为n的方程总数。
具体参考 生成函数,也叫母函数。
*/
#include <iostream>
using namespace std;
const int N=130;
int a[N];
int b[N];
int c[N];
void Poly()
{
    memset(c,0,sizeof(c));
    for(int i=0;i<N;i++)
        for(int j=0;j<N-i;j++)
        {
            c[i+j]+=a[i]*b[j];
        }
}
void Init()
{
    memset(a,0,sizeof(a));
    memset(c,0,sizeof(c));
    for(int i=0;i<N;i++)
        a[i]=1;
    for(int k=2;k<N;k++)
    {
        memset(b,0,sizeof(b));
        for(int i=0;i<N;i=i+k)
        {
            b[i]=1;
        }
        Poly();
        memcpy(a,c,sizeof(c));
    }
}
int main()
{
    int n;
    Init();
    while(scanf("%d",&n)!=EOF)
    {
        printf("%d\n",a[n]);
    }
}
