using namespace std;
int n;
int a[N],b[N],ab[N];//数组a表示一个多项式的系数，下标表示指数 ab表示a和b 乘积

int Num()
{
    int i,j,k;
	
    memset(ab, 0 ,sizeof(ab));
	for(i = 0; i <= n ; i++)
	  ab[i] = 1;//第一次要赋值为全1，为下面循环准备
	
    for(k = 2; k <= n; k++)
    {
	
        memcpy(b, ab, sizeof(ab));//把ab 复制给 b 开始新的循环

	for(i = 0; i <= n; i++)
	{
		a[i] = 0;
		ab[i] = 0;
