    for(int k=m[0];k<=Max;k++)
        f[0][k]=k*(hire+salary);
    for(int i=1;i<n;i++)
    {
        for(int k=m[i];k<=Max;k++)
        {
            f[i][k]=INT_MAX;
            for(int j=m[i-1];j<=Max;j++)
            {
                if(j<k)
                    t=k*salary+f[i-1][j]+(k-j)*hire;
                else
                    t=k*salary+f[i-1][j]+(j-k)*fire;
                if(f[i][k]>t)
                    f[i][k]=t;
            }
        }
    }
    int ans=INT_MAX;
    for(int k=m[n-1];k<=Max;k++)
