        ry=FindRoot(y);
        if(rx==ry)//同性恋
        {
            ans=false;
            continue;
        }
        if(opp[x]==0)//合并opp[x]与y
            opp[x]=y;
        else
            Merge(opp[x],y);
        if(opp[y]==0)//合并opp[y]与x
            opp[y]=x;
        else
            Merge(x,opp[y]);
    }
}
int main()
{
