个馅饼。
则在|x-5|<=t时
ans[t][x]=Max{ans[t-1][x-1],ans[t-1][x],ans[t-1][x+1]}+map[t][x];
注意：N＝100000时会WA，晕死。
*/
#include <iostream>
#include <cmath>
using namespace std;
const int N=100005;
const int M=11;
int map[N][M];
int n;
int ans[N][M];
int step[2]={1,-1};
int mt;
void DP()
{
    int Max;
    int x1;
    int MaxOut=0;
    memset(ans,0,sizeof(ans));
//    ans[0][5]=map[0][5];
    for(int t=1;t<=mt;t++)
    {
        for(int x=0;x<=10;x++)
        {
            if(abs(x-5)>t)
                continue;
            Max=ans[t-1][x];
            for(int k=0;k<2;k++)
            {
                x1=x+step[k];
                if(x1<0||x1>10)
                    continue;
                if(Max<ans[t-1][x1])
                    Max=ans[t-1][x1];
            }
            ans[t][x]=Max+map[t][x];
            if(ans[t][x]>MaxOut)
                MaxOut=ans[t][x];
        }
    }

    printf("%d\n",MaxOut);
}
int main()
{
    int x,t;
    while(scanf("%d",&n),n)
    {
        memset(map,0,sizeof(map));
        mt=0;
        for(int i=0;i<n;i++)
        {
            scanf("%d %d",&x,&t);
            map[t][x]++;
            if(t>mt)
                mt=t;
        }
        DP();
    }
}
}}}

