    for(int i=1;i<=n;i++)
        scanf("%lf",&p[i]);
    n++;
    p[n]=len;
    n++;
}
/*
从第x个充电点直接到第y个充电点，到第y个充电点时的最短时间。
如果时间相同，电动车余量最大。
*/
void Go(int x,int y,double &tt,double &tc)
{
    double t1=Time[x];
    double t2=Time[x];
    double c1=Cap[x];
    double c2=Cap[x];
    double len=p[y]-p[x];
    //在第x个点不充电直接走
    if(len<=c1)
    {
        t1+=len/vt1;
        c1-=len;
    }
    else
    {
        t1+=c1/vt1;
        len-=c1;
        t1+=len/vt2;
        c1=0;
    }

    //在第x个点充电后再走。
    t2+=t;
    c2=c;
    len=p[y]-p[x];
    if(len<=c2)
    {
        t2+=len/vt1;
        c2-=len;
    }
    else
    {
        t2+=c2/vt1;
        len-=c2;
        c2=0;
        t2+=len/vt2;
    }
    if(t1<t2||t1==t2&&c1>c2)
    {
        tt=t1;
        tc=c1;
    }
    else
    {
        tt=t2;
        tc=c2;
    }
}

void DP()
{
    memset(Time,0,sizeof(Time));
    memset(Cap,0,sizeof(Cap));
    Time[0]=0;
    Cap[0]=c;
    double Min,Maxc;
    double tt,tc;
    for(int i=1;i<n;i++)
    {
        Min=INT_MAX;
        Maxc=INT_MIN;
        for(int j=0;j<i;j++)
        {
            Go(j,i,tt,tc);
            if(tt<Min||tt==Min&&tc>Maxc)
            {
                Min=tt;
                Maxc=tc;
            }
        }
        Time[i]=Min;
        Cap[i]=Maxc;
    }
    double t1=len/vr;
    if(t1<Time[n-1])
        printf("Good job,rabbit!\n");
    else
        printf("What a pity rabbit!\n");
}

int main()
{
    while(scanf("%lf",&len)!=EOF)
    {
        Init();
        DP();
    }
}
}}}

