	int oneNode;
	bool bb;
	bool bc=true;
	int nCase=0;
	while(cin>>term1 && term1){
		cin>>term2;
		//initialize
		oneNode=term1;		//use this node to be the initial node of DFS
		ccc=1;
		nCase++;
		fill(record+1, record+1001, 0);
		record[oneNode]=-1;
		for(i=1; i<1001; i++){
			TS[i].connect.clear();
			//TS[i].child.clear();
			TS[i].visited=false;
			TS[i].minAncestor=i;
			TS[i].parent=i;
		}
		//
		MyInsert(TS[term1].connect, term2);
		MyInsert(TS[term2].connect, term1);
		while(cin>>term1 && term1){
			cin>>term2;
			MyInsert(TS[term1].connect, term2);
			MyInsert(TS[term2].connect, term1);			
		}
		DFS(oneNode, oneNode);
//		record[oneNode]=TS[oneNode].child.size();
		Check(oneNode);
		bb=false;
		if(bc)	bc=false;
		else cout<<endl;
