        for(i=2; i<=19; i++){
                cin>>num;
                for(j=1; j<=num; j++){
                        cin>>tem1;
                        counList[i].paths[tem1]=1;
                        counList[tem1].paths[i]=1;
                }
        }

        return true;
}

int main(){
